function emitterAssert(bool $ok,string $message):void{if(!$ok){fwrite(STDERR,"ASSERTION FAILED: {$message}\n");exit(1);}}
$root=dirname(__DIR__);$form=file_get_contents($root.'/public/includes/establishment_form.php');$data=file_get_contents($root.'/src/Services/EstablishmentData.php');$repo=file_get_contents($root.'/src/Repositories/TenantEstablishmentRepository.php');$migration=file_get_contents($root.'/migrations/20260821_create_tenant_establishments.sql');$coverage=file_get_contents($root.'/docs/fiscal/FISCAL-01D-establishment-field-completion.md');$rules=file_get_contents($root.'/docs/fiscal/FISCAL-FIELD-IMPLEMENTATION-RULES.md');
