emitterAssert(str_contains($repo,'WHERE tenant_id = :tenant_id'),'tenant scoped repository');emitterAssert(!str_contains($form,'name="access_key"')&&!str_contains($form,'name="certificate"')&&!str_contains($form,'name="protocol"'),'derived/secret/SEFAZ values are not inputs');foreach(['USER_INPUT','CONFIGURATION','DERIVED','CALCULATED','TAX_RULE','SECRET','SEFAZ_RESPONSE','Snapshot'] as $rule)emitterAssert(str_contains($rules,$rule),"rules cover {$rule}");echo "Fiscal01DEmitterCoverage OK\n";
